/**
 * Get all species for ConceptoArte project
 * @returns {Array} Array of species objects ready for TreeCard component
 */
export const getAllSpecies = () => {
  return conceptoArteSpecies;
};

/**
 * Get a single species by name
 * @param {String} name - Common or scientific name
 * @returns {Object|null} Species object or null if not found
 */
export const getSpeciesByName = (name) => {
  return conceptoArteSpecies.find(
    s => s.commonName === name || s.scientificName === name
  ) || null;
};

/**
 * Get species by role (pioneer, secondary, climax)
 * @param {String} role - Ecological role
 * @returns {Array} Filtered species array
 */
export const getSpeciesByRole = (role) => {
  return conceptoArteSpecies.filter(s => s.role === role);
};

/**
 * Get project statistics
 * @returns {Object} Project stats
 */
export const getProjectStats = () => {
  return {
    totalSpecies: conceptoArteSpecies.length,
    totalTrees: conceptoArteSpecies.reduce((sum, s) => sum + s.availability.needed, 0),
    byRole: {
      pioneer: conceptoArteSpecies.filter(s => s.role === 'pioneer').length,
      secondary: conceptoArteSpecies.filter(s => s.role === 'secondary').length,
      climax: conceptoArteSpecies.filter(s => s.role === 'climax').length
    }
  };
};

export default {
  getAllSpecies,
  getSpeciesByName,
  getSpeciesByRole,
  getProjectStats
};
